import { useAccessibility } from "intelliaccess-framework";

function Navbar() {
  const { setProfile } = useAccessibility();

  return (
    <nav className="navbar">
      <h2>Student Notice Board</h2>
      <div className="navbar-buttons">
        <button onClick={() => setProfile("lowVision")}>Low Vision</button>
        <button onClick={() => setProfile("dyslexia")}>Dyslexia</button>
        <button onClick={() => setProfile("colourBlind")}>Colour Blind</button>
        <button onClick={() => setProfile("elderly")}>Elderly</button>
        <button onClick={() => setProfile("none")}>Reset</button>
      </div>
    </nav>
  );
}

export default Navbar;
